INSERT INTO `ab_blocks` (`id`, `category_id`, `blockid`, `label`, `media`, `attributes`, `content`, `status`, `seq`, `theme_id`, `created_at`, `updated_at`) VALUES
(54, 2, 'box-icon-1', 'Box Icon 1', '<svg xmlns=\"http://www.w3.org/2000/svg\" \r\n height=\"50px\">\r\n  <!-- Embedding an image -->\r\n  <image xlink:href=\"https://test.webfire.in/public/admin/theme/img/user.jpg\" width=\"100%\" height=\"100%\" />\r\n</svg>', '{class : \'\',id:\'\'}', '<div class=\"feature-icon-wrapper section-space--ptb_100\">\n                <div class=\"container\">\n\n                    <div class=\"row\">\n                        <div class=\"col-lg-12\">\n                            <div class=\"section-title-wrap text-center section-space--mb_40\">\n                                <h6 class=\"section-sub-title mb-20\">Industries we Serve</h6>\n                                <h3 class=\"heading\">For your very specific industry, <br> we have <span class=\"text-color-primary\"> highly-tailored IT solutions.</span></h3>\n                            </div>\n                        </div>\n                    </div>\n\n                    <div class=\"row\">\n                        <div class=\"col-12\">\n                            <div class=\"feature-list__one\">\n                                <div class=\"row\">\n\n                                    <div class=\"col-lg-3 col-md-6\">\n                                        <!-- ht-box-icon Start -->\n                                        <div class=\"ht-box-icon style-01 single-svg-icon-box\">\n                                            <div class=\"icon-box-wrap\">\n                                                <div class=\"icon\">\n\n                                                    <!--<img src=\"assets/images/svg/linea-basic-heart.svg\" alt=\"\">-->\n\n                                                    <div class=\"svg-icon\" id=\"svg-icon-1\" data-svg-icon=\"assets/images/svg/linea-basic-heart.svg\"><svg version=\"1.1\" id=\"Layer_1\" xmlns=\"http://www.w3.org/2000/svg\" xmlns:xlink=\"http://www.w3.org/1999/xlink\" x=\"0px\" y=\"0px\" width=\"100%\" height=\"100%\" viewBox=\"0 0 64 64\" enable-background=\"new 0 0 64 64\" xml:space=\"preserve\">\n<path fill=\"none\" stroke=\"#000000\" stroke-width=\"2\" stroke-miterlimit=\"10\" d=\"M1,21c0,20,31,38,31,38s31-18,31-38  c0-8.285-6-16-15-16c-8.285,0-16,5.715-16,14c0-8.285-7.715-14-16-14C7,5,1,12.715,1,21z\" style=\"stroke-dasharray: 198, 200; stroke-dashoffset: 0;\"></path>\n<style xmlns=\"\" type=\"text/css\" id=\"igtranslator-color\"></style></svg></div>\n                                                </div>\n                                                <div class=\"content\">\n                                                    <h5 class=\"heading\">IT Design </h5>\n                                                    <div class=\"text\">We provide the most responsive and functional IT design for companies and businesses worldwide.\n                                                    </div>\n                                                    <div class=\"feature-btn\">\n                                                        <a href=\"#\">\n                                                            <span class=\"button-text\">Discover now</span>\n                                                            <i class=\"fas fa-arrow-right\"></i>\n                                                        </a>\n                                                    </div>\n                                                </div>\n                                            </div>\n                                        </div>\n                                        <!-- ht-box-icon End -->\n                                    </div>\n                                    <div class=\"col-lg-3 col-md-6\">\n                                        <!-- ht-box-icon Start -->\n                                        <div class=\"ht-box-icon style-01 single-svg-icon-box\">\n                                            <div class=\"icon-box-wrap\">\n                                                <