(242, 390, '* { box-sizing: border-box; } body {margin: 0;}*{box-sizing:border-box;margin:0;padding:0;scroll-behavior:smooth;}body{margin:0;overflow-x:hidden;font-family:&quot;Poppins&quot;, sans-serif;font-size:16px;}#iu3f9i{width:100%;}ul{list-style:none;}input{overflow:hidden;}.contact-sec .contact-ul li, .contact-ul b{font-size:20px;margin:10px 0;font-family:Cambria, Cochin, Georgia, Times, &quot;Times New Roman&quot;, serif;word-wrap:break-word;}.contact-sec .contact-ul i{font-size:18px;padding:10px;margin-right:10px;border-radius:50%;}.contact-detail a{color:#000;text-decoration:none;}.contact-sec .contact-ul li b:hover{color:#f93;}.contact-sec .contact-ul li .fa-location-dot{color:#f44337;border:2px solid #f4433790;}.contact-sec .contact-ul li .fa-phone{color:#00b055;border:2px solid #00b05590;}.contact-sec .contact-ul li .fa-envelope{color:#ff6347;border:2px solid #ff634790;}.contact-detail span{width:400px;display:flex;justify-content:center;}.contact-detail span a{font-size:20px;padding:6px 12px;color:#000;border-radius:50%;margin:0px 5px;}.contact-detail span .fb{color:#3b5998;border:3px solid #3b5998;}.contact-detail span .fb:hover{color:#fff;background-color:#3b5998;}.contact-detail span .insta{color:#833ab4;border:3px solid #833ab4;}.contact-detail span .insta:hover{color:#fff;background-color:#833ab4;}.contact-detail span .twitter{color:#00acee;border:3px solid #00acee;}.contact-detail span .twitter:hover{color:#fff;background-color:#00acee;}form.contFrm{max-width:396px;margin:auto;}.contFrm textarea{height:75px;padding-top:5px;}.row{display:flex;justify-content:flex-start;align-items:stretch;flex-wrap:nowrap;padding:10px;}.cell{min-height:75px;flex-grow:1;flex-basis:100%;}#imw0s{flex-basis:30%;}#ikaez{flex-basis:70%;}#i3ebx{height:312px;}#iusjp{height:100%;width:100%;}@media (max-width: 991px){.contact-sec .contact-ul li, .contact-ul b{font-size:18px;}.contact-sec .contact-ul i{font-size:14px;padding:6px;margin-right:6px;}}@media (max-width: 768px){.row{flex-wrap:wrap;}}@media (max-width: 767px){.contact-detail span{width:auto;}.contact-detail span a{font-size:18px;padding:5px 10px;color:#000;border-radius:50%;margin:0px 5px 20px;}}@media (max-width: 575px){.contact-sec .contact-ul i{border:none;}}@media (max-width: 480px){.contact-sec .contact-ul li, .contact-ul b{font-size:16px;}}', '&lt;section class=&quot;about_section&quot;&gt;&lt;div class=&quot;container-fluid&quot;&gt;&lt;/div&gt;&lt;/section&gt;&lt;!-- end about section --&gt;&lt;!-- client section --&gt;&lt;!-- end client section --&gt;&lt;!-- contact section --&gt;&lt;img id=&quot;iu3f9i&quot; draggable=&quot;true&quot; src=&quot;https://test.webfire.in/public/temp/2/contact-banner.jpg&quot; class=&quot;gjs-selected&quot;/&gt;&lt;div class=&quot;row&quot; id=&quot;i3ebx&quot;&gt;&lt;div class=&quot;cell&quot; id=&quot;imw0s&quot;&gt;&lt;div id=&quot;idemm&quot;&gt;[ab-form id=230]	&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;cell&quot; id=&quot;ikaez&quot;&gt;&lt;iframe frameborder=&quot;0&quot; src=&quot;https://maps.google.com/maps?&amp;q=Firozabad Uttar Pradesh&amp;z=7&amp;t=w&amp;output=embed&quot; class=&quot;gjs-no-pointer&quot; id=&quot;iusjp&quot;&gt;&lt;/iframe&gt;&lt;/div&gt;&lt;/div&gt;&lt;!-- end contact section --&gt;&lt;!-- info section --&gt;&lt;!-- end info_section --&gt;', 34, '1', '2024-02-16 07:13:40', '2024-04-07 08:38:25');
